func tZeros(b *port.Buf, n int32) int32 {
	// The caller's part of the contract: `n` zero bytes to paint on.
	var i int32 = 0
	for i < n {
		port.BufPush(b, 0)
		i += 1
	}
	return 0
}

func tDec(emonT *testing.T, ws *port.Cells, d []byte, k int32, cols int32, rows int32, flags int32, want int32, nbytes int32, b0 int32, b1 int32, b2 int32, b3 int32, msg string) int32 {
	var out *port.Buf = port.NewBuf()
	tZeros(out, rows*((cols+7)/8))
	var st int32 = ccitt.CcDecode(d, 0, port.BlobLen(d), k, cols, rows, flags, out, ws)
	port.AssertEq(emonT, st, want, msg)
	if want == 0 {
		port.AssertEq(emonT, port.BufLen(out), nbytes, msg)
		if b0 >= 0 {
			port.AssertEq(emonT, port.BufAt(out, 0), b0, msg)
		}
		if b1 >= 0 {
			port.AssertEq(emonT, port.BufAt(out, 1), b1, msg)
		}
		if b2 >= 0 {
			port.AssertEq(emonT, port.BufAt(out, 2), b2, msg)
		}
		if b3 >= 0 {
			port.AssertEq(emonT, port.BufAt(out, 3), b3, msg)
		}
	}
	return 0
}

func TestCcittOutTooSmall(emonT *testing.T) {
	// `out` must already hold the rows: 16 x 2 pixels is four bytes, and three are not enough (status 3).
	var ws *port.Cells = port.NewCells()
	var out *port.Buf = port.NewBuf()
	tZeros(out, 3)
	port.AssertEq(emonT, ccitt.CcDecode(port.HexBlob("f0"), 0, 1, -1, 16, 2, 0, out, ws), 3, "a buffer short of the rows")
}

