func TestCcittG31d(emonT *testing.T) {
	var ws *port.Cells = port.NewCells()
	tDec(emonT, ws, port.HexBlob("001b73"), 0, 16, 1, 0, 0, 2, 15, 0, -1, -1, "G3 1-D with an EOL")
	tDec(emonT, ws, port.HexBlob("001b73"), 0, 16, 1, 4, 0, 2, 15, 0, -1, -1, "G3 1-D with an EOL, EndOfLine required")
	tDec(emonT, ws, port.HexBlob("b730"), 0, 16, 1, 0, 0, 2, 15, 0, -1, -1, "G3 1-D with no EOL at all")
	tDec(emonT, ws, port.HexBlob("b730"), 0, 16, 1, 4, 1, 0, -1, -1, -1, -1, "G3 1-D with no EOL where one is required")
}

