func TestCcittFaults(emonT *testing.T) {
	var ws *port.Cells = port.NewCells()
	tDec(emonT, ws, port.HexBlob("36"), -1, 16, 1, 0, 1, 0, -1, -1, -1, -1, "G4: truncated inside a code")
	tDec(emonT, ws, port.HexBlob("f0"), -1, 16, 5, 0, 1, 0, -1, -1, -1, -1, "G4: four rows of five")
	tDec(emonT, ws, port.HexBlob("0000"), -1, 16, 1, 0, 1, 0, -1, -1, -1, -1, "G4: no such mode")
	tDec(emonT, ws, port.HexBlob("001001"), -1, 16, 1, 0, 1, 0, -1, -1, -1, -1, "G4: EOFB with rows owed")
	tDec(emonT, ws, port.HexBlob("d9a8"), 0, 16, 1, 0, 1, 0, -1, -1, -1, -1, "G3: a run past the width")
	tDec(emonT, ws, port.HexBlob("001001"), 0, 16, 1, 0, 1, 0, -1, -1, -1, -1, "G3: RTC with rows owed")
	tDec(emonT, ws, port.HexBlob("f0"), -1, 0, 1, 0, 1, 0, -1, -1, -1, -1, "no width")
	tDec(emonT, ws, port.HexBlob("f0"), -1, 16, 0, 0, 1, 0, -1, -1, -1, -1, "no rows")
}

